
.opening-shell {
  width: min(760px, 100%);
  margin: 8px auto;
  padding: 16px;
  display: grid;
  gap: 14px;
  color: #e8eaf0;
  background:
    radial-gradient(circle at top left, rgba(220, 60, 30, 0.15), transparent 32%),
    radial-gradient(circle at bottom right, rgba(30, 90, 200, 0.12), transparent 36%),
    linear-gradient(180deg, rgba(16, 14, 22, 0.98), rgba(10, 12, 18, 0.98));
  border: 1px solid rgba(220, 80, 40, 0.22);
  border-radius: 24px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.42);
  font-family: 'Segoe UI', 'Microsoft YaHei', sans-serif;
}

.panel {
  padding: 18px;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.03), rgba(200, 80, 30, 0.04)),
    rgba(255, 255, 255, 0.02);
}

.section-title {
  font-size: 14px;
  font-weight: 600;
  color: rgba(255, 180, 90, 0.9);
  margin-bottom: 12px;
  letter-spacing: 0.06em;
}

.hero-card {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: flex-start;
}

.hero-copy h1 {
  margin: 6px 0 8px;
  font-size: 34px;
  letter-spacing: 0.12em;
  background: linear-gradient(135deg, #ff6a3d, #ffc93c, #ff6a3d);
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  font-weight: 800;
}

.hero-copy p {
  margin: 0;
  line-height: 1.7;
  color: rgba(232, 234, 240, 0.72);
  font-size: 14px;
}

.eyebrow {
  font-size: 11px;
  letter-spacing: 0.28em;
  color: #ff6a3d;
}

.hero-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
  flex-shrink: 0;
}

.hero-tags span {
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid rgba(255, 106, 61, 0.22);
  background: rgba(255, 106, 61, 0.08);
  white-space: nowrap;
  color: #ffc93c;
  font-size: 12px;
}

.field-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.field {
  display: grid;
  gap: 6px;
}

.field-full {
  grid-column: 1 / -1;
}

.field span {
  color: rgba(232, 234, 240, 0.65);
  font-size: 12px;
  letter-spacing: 0.04em;
}

.field input,
.field select,
.field textarea {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  padding: 12px 13px;
  border: 1px solid rgba(255, 106, 61, 0.16);
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(14, 14, 18, 0.95), rgba(22, 18, 16, 0.95)),
    rgba(0, 0, 0, 0.3);
  color: #f0e8dc;
  font: inherit;
  font-size: 14px;
  transition: border-color 0.2s;
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  outline: none;
  border-color: rgba(255, 106, 61, 0.5);
}

.field textarea {
  resize: vertical;
  line-height: 1.6;
}

.summary-panel .section-title {
  margin-bottom: 10px;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.summary-card {
  padding: 14px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.07);
}

.summary-card span {
  color: rgba(232, 234, 240, 0.55);
  font-size: 11px;
  letter-spacing: 0.04em;
}

.summary-card strong {
  display: block;
  margin: 4px 0;
  color: #ffc93c;
  font-size: 14px;
}

.summary-card p {
  margin: 0;
  color: rgba(232, 234, 240, 0.5);
  font-size: 12px;
  line-height: 1.4;
}

.action-row {
  display: flex;
  justify-content: center;
}

.primary-button {
  appearance: none;
  border-radius: 999px;
  min-height: 48px;
  padding: 0 28px;
  font: inherit;
  cursor: pointer;
  border: 0;
  color: #1a0f08;
  background: linear-gradient(135deg, #ff6a3d, #ffc93c);
  width: 100%;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.06em;
  transition: filter 0.2s, transform 0.1s;
}

.primary-button:hover:not(:disabled) {
  filter: brightness(1.12);
  transform: translateY(-1px);
}

.primary-button:active:not(:disabled) {
  transform: translateY(0);
}

.primary-button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

@media (max-width: 760px) {
  .field-grid,
  .summary-grid {
    grid-template-columns: 1fr;
  }
  .hero-card {
    flex-direction: column;
  }
  .hero-tags {
    justify-content: flex-start;
  }
}
